from common import *  # noqa: F401,F403

# ---------------------------------------------------------------- diagram: anatomy of -rwxr-x---
_cols = [(8, 64, "bx", "-", "type"), (120, 112, "bxo", "rwx", "owner (u)"), (280, 112, "bxt", "r-x", "group (g)"),
         (440, 112, "bxg", "---", "others (o)")]
_body = [cap(280, 24, "ls -l shows -rwxr-x--- after chmod 750 deploy.sh")]
for x, w, cls, label, sub in _cols:
    _body.append(box(x, 44, w, 56, cls, label, sub))
for (x, w, _, _, _), (digits, sumtxt) in zip(_cols[1:], [("7", "4 + 2 + 1"), ("5", "4 + 0 + 1"), ("0", "0 + 0 + 0")]):
    _body.append(arrow(x + w / 2, 104, x + w / 2, 128))
    _body.append(cap(x + w / 2, 150, digits, size=13, cls="t"))
    _body.append(cap(x + w / 2, 170, sumtxt))
_body.append(cap(40, 150, "file", size=13, cls="t"))
_body.append(cap(280, 198, "r = 4 (read), w = 2 (write), x = 1 (execute)"))
DIAGRAM = svg(212, "The permission string -rwxr-x--- split into type, owner rwx, group r-x and others ---, which add up to the octal digits 7, 5 and 0", _body)

